reports=data['reports']
visible=[r for r in reports if r['received_time']<=data['knowledge_cutoff']]
best={}
for r in visible:
    eid=r['event_id']
    if eid not in best or r['revision']>best[eid]['revision'] or (r['revision']==best[eid]['revision'] and r['received_time']>best[eid]['received_time']):
        best[eid]=r
chosen=[r for r in best.values() if r['event_time']<=data['target_time']]
chosen_sorted=sorted(chosen,key=lambda r:(r['event_time'], r['event_id']))
len(visible), len(best), len(chosen_sorted), chosen_sorted[:5], chosen_sorted[-5:]

stock=data['initial_stock']
hist_lost=0
stockouts=[]
for r in chosen_sorted:
    q=r['quantity']
    if r['kind']=='receipt':
        stock += q
    else:
        unmet=max(0,q-stock)
        if unmet>0: stockouts.append((r['event_time'], r['event_id'], unmet, stock, q))
        hist_lost += unmet
        stock -= min(stock,q)
stock, hist_lost, stockouts[:10], len(stockouts)
